async def do_async(gen: Generator[Result[T, E], None, None]) -> Result[T, E]:
    """Asynchronous version of do notation for Result.

    This function works with generator expressions that contain awaited values.

    Usage:

    ``` python
    result = await do_async(
        Ok(len(x) + int(y) + z)
        for x in await get_async_result_1()
        for y in await get_async_result_2()
        for z in get_sync_result_3()
    )
    ```

    NOTE: If you exclude the type annotation e.g. `Result[float, int]`
    your type checker might be unable to infer the return type.
    To avoid an error, you might need to help it with the type hint.
    """
    # Handle both regular generators and async generators
    if inspect.isasyncgen(gen):
        try:
            # For async generators, we need to await the first item
            item = await gen.__anext__()
            return item
        except DoException as e:
            out: Err[E] = e.err  # type: ignore
            return out
        except StopAsyncIteration:
            # This should not happen with generator expressions
            raise ValueError("Empty async generator in do_async")
    else:
        # For regular generators (which can happen in certain cases with await inside)
        try:
            return next(gen)
        except DoException as e:
            out: Err[E] = e.err  # type: ignore
            return out

